CREATE TABLE categories(id uuid PRIMARY KEY,name varchar(255) NOT NULL,slug varchar(255) NOT NULL UNIQUE,active boolean NOT NULL DEFAULT true);
CREATE TABLE books(id uuid PRIMARY KEY,slug varchar(255) NOT NULL UNIQUE,title varchar(255) NOT NULL,author varchar(255) NOT NULL,description text NOT NULL,price bigint NOT NULL CHECK(price BETWEEN 1000 AND 100000000),stock integer NOT NULL CHECK(stock>=0),active boolean NOT NULL,category_id uuid NOT NULL REFERENCES categories(id),cover integer NOT NULL CHECK(cover BETWEEN 1 AND 18));
CREATE INDEX books_category_idx ON books(category_id);
CREATE TABLE members(id uuid PRIMARY KEY,email varchar(255) NOT NULL UNIQUE,name varchar(255) NOT NULL,password_hash varchar(255) NOT NULL,role varchar(255) NOT NULL CHECK(role IN ('CUSTOMER','ADMIN')));
CREATE TABLE coupons(code varchar(255) PRIMARY KEY,kind varchar(255) NOT NULL CHECK(kind IN ('FIXED','PERCENT')),value bigint NOT NULL CHECK(value>0 AND (kind<>'PERCENT' OR value<=100)),minimum bigint NOT NULL CHECK(minimum>=0),active boolean NOT NULL,expires_at timestamptz);
CREATE TABLE orders(id uuid PRIMARY KEY,member_id uuid NOT NULL REFERENCES members(id),checkout_key uuid NOT NULL UNIQUE,code varchar(255) NOT NULL UNIQUE,method varchar(255) NOT NULL CHECK(method IN ('COD','STRIPE')),name varchar(255) NOT NULL,phone varchar(255) NOT NULL,address varchar(255) NOT NULL,discount bigint NOT NULL CHECK(discount>=0),shipping bigint NOT NULL CHECK(shipping>=0),total bigint NOT NULL CHECK(total>=0),created_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,status varchar(255) NOT NULL CHECK(status IN ('PENDING_PAYMENT','CONFIRMED','SHIPPING','COMPLETED','CANCELLED','EXPIRED')),paid boolean NOT NULL DEFAULT false,stock_released boolean NOT NULL DEFAULT false,session_id varchar(255) UNIQUE,payment_url text,charged_currency varchar(255),charged_amount bigint NOT NULL DEFAULT 0);
CREATE INDEX orders_member_idx ON orders(member_id,created_at DESC);
CREATE INDEX orders_pending_idx ON orders(created_at) WHERE status='PENDING_PAYMENT';
CREATE TABLE order_lines(order_id uuid NOT NULL REFERENCES orders(id),line_number integer NOT NULL,book_id uuid NOT NULL REFERENCES books(id),title varchar(255) NOT NULL,unit_price bigint NOT NULL CHECK(unit_price>=0),quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 99),PRIMARY KEY(order_id,line_number));
CREATE TABLE payment_events(event_id varchar(255) PRIMARY KEY,session_id varchar(255) NOT NULL,received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE spring_session(primary_id char(36) PRIMARY KEY,session_id char(36) NOT NULL,creation_time bigint NOT NULL,last_access_time bigint NOT NULL,max_inactive_interval integer NOT NULL,expiry_time bigint NOT NULL,principal_name varchar(100));
CREATE UNIQUE INDEX spring_session_ix1 ON spring_session(session_id);
CREATE INDEX spring_session_ix2 ON spring_session(expiry_time);
CREATE INDEX spring_session_ix3 ON spring_session(principal_name);
CREATE TABLE spring_session_attributes(session_primary_id char(36) NOT NULL REFERENCES spring_session(primary_id) ON DELETE CASCADE,attribute_name varchar(200) NOT NULL,attribute_bytes bytea NOT NULL,PRIMARY KEY(session_primary_id,attribute_name));
